-- Included in the transactional invoicing scenario, before its final ROLLBACK.
reset role;
select pg_temp.login('patron_a');
set local role authenticated;
do $$
declare v_org uuid; v_source public.invoices; v_draft public.invoices; v_retry public.invoices;
  v_before jsonb; v_counter integer; v_credits integer; v_invoice_count integer;
begin
  select id into v_org from public.organizations where slug = 'factu-a';
  insert into public.invoices (organization_id) values (v_org) returning * into v_source;
  perform pg_temp.complete_invoice(v_source.id);
  insert into public.invoice_items (invoice_id,organization_id,description,quantity,unit_price_cents,vat_rate)
    values (v_source.id,v_org,'Seconde prestation, autre taux',2,12345,8.5);
  select * into v_source from public.invoices where id = v_source.id;
  select * into v_source from public.issue_invoice(v_source.id,v_source.updated_at);
  v_before := to_jsonb(v_source);
  reset role;
  select last_value into v_counter from public.invoice_counters where organization_id = v_org and document_type = 'invoice' and year = extract(year from current_date);
  select coalesce(sum(last_value),0) into v_credits from public.invoice_counters where organization_id = v_org and document_type = 'credit_note';
  set local role authenticated;
  select * into v_draft from public.create_full_credit_note_draft(v_source.id,v_source.updated_at,'Annulation complète de la prestation - TEST');
  perform pg_temp.ok(v_draft.status = 'draft' and v_draft.issued_at is null and v_draft.reference like 'BR-%','Avoir créé en brouillon sans numéro définitif');
  perform pg_temp.ok(v_draft.corrected_invoice_reference = v_source.reference and v_draft.corrected_invoice_issued_at = v_source.issued_at,'Référence et date d''origine figées dans l''avoir');
  perform pg_temp.ok(v_draft.customer_name = v_source.customer_name and v_draft.corrects_invoice_id = v_source.id,'Destinataire et lien d''origine repris');
  perform pg_temp.ok((select total_cents from public.invoice_totals where invoice_id=v_draft.id) = (select total_cents from public.invoice_totals where invoice_id=v_source.id),'Avoir total : même total avec deux taux de TVA');
  select * into v_retry from public.create_full_credit_note_draft(v_source.id,v_source.updated_at,'Deuxième clic');
  perform pg_temp.ok(v_retry.id = v_draft.id and v_retry.credit_note_reason = v_draft.credit_note_reason,'Un double clic retrouve le même brouillon sans le réécrire');
  perform pg_temp.ok((select to_jsonb(i) from public.invoices i where id=v_source.id) = v_before,'La préparation ne modifie pas la facture d''origine');
  reset role;
  perform pg_temp.ok((select last_value from public.invoice_counters where organization_id=v_org and document_type='invoice' and year=extract(year from current_date)) = v_counter,'Compteur des factures inchangé');
  perform pg_temp.ok((select coalesce(sum(last_value),0) from public.invoice_counters where organization_id=v_org and document_type='credit_note') = v_credits,'Compteur des avoirs inchangé avant émission');
  set local role authenticated;
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_source.id,now(),'Version périmée'),'Version périmée refusée');
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_draft.id,v_draft.updated_at,'Avoir d''avoir'),'Un avoir ne corrige pas un avoir');
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_source.id,v_source.updated_at,' '),'Motif vide refusé');
  perform pg_temp.refuses(format('update public.invoices set document_type=''invoice'',corrects_invoice_id=null where id=%L',v_draft.id),'Type et lien d''origine non modifiables');
  perform pg_temp.refuses(format('insert into public.invoices(organization_id,document_type,corrects_invoice_id,credit_note_reason) values(%L,''credit_note'',%L,''Doublon direct'')',v_org,v_source.id),'Un doublon direct est refusé par la base');

  select * into v_retry from public.save_full_credit_note_draft(v_draft.id,v_draft.updated_at,'Motif précisé - TEST',current_date+10,'Remboursement convenu sous dix jours.');
  perform pg_temp.ok(v_retry.credit_note_reason='Motif précisé - TEST' and v_retry.updated_at<>v_draft.updated_at,'Motif et modalités du brouillon enregistrés');
  perform pg_temp.refuses(format('select public.save_full_credit_note_draft(%L,%L,%L,current_date,%L)',v_draft.id,v_draft.updated_at,'Périmé','Sans effet'),'Enregistrement périmé refusé');
  v_draft := v_retry;
  update public.invoice_items set unit_price_cents=unit_price_cents+1 where invoice_id=v_draft.id;
  select * into v_draft from public.invoices where id=v_draft.id;
  perform pg_temp.refuses(format('select public.issue_invoice(%L,%L)',v_draft.id,v_draft.updated_at),'Émission d''un montant différent refusée');
  update public.invoice_items set unit_price_cents=unit_price_cents-1 where invoice_id=v_draft.id;
  update public.invoices set customer_name='Autre destinataire' where id=v_draft.id;
  select * into v_draft from public.invoices where id=v_draft.id;
  perform pg_temp.refuses(format('update public.invoices set status=''issued'' where id=%L',v_draft.id),'Émission directe pour un autre destinataire refusée');
  update public.invoices set customer_name=v_source.customer_name where id=v_draft.id;
  select * into v_draft from public.invoices where id=v_draft.id;
  select * into v_draft from public.issue_invoice(v_draft.id,v_draft.updated_at);
  perform pg_temp.ok(v_draft.status='issued' and v_draft.reference like 'AV-%','Émission explicite dans la série des avoirs');
  perform pg_temp.ok((select to_jsonb(i) from public.invoices i where id=v_source.id)=v_before,'La facture d''origine reste intacte après émission de l''avoir');
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_source.id,v_source.updated_at,'Déjà créditée'),'Une facture ne reçoit pas deux avoirs totaux');
  perform pg_temp.refuses(format('update public.invoices set credit_note_reason=''Autre motif'' where id=%L',v_draft.id),'Avoir émis immuable');
  perform pg_temp.refuses(format('delete from public.invoices where id=%L',v_draft.id),'Avoir émis non supprimable');
  reset role;
  perform pg_temp.ok((select coalesce(sum(last_value),0) from public.invoice_counters where organization_id=v_org and document_type='credit_note')=v_credits+1,'Un seul numéro d''avoir consommé, aucun sur les refus');
  set local role authenticated;

  perform pg_temp.login('patron_b');
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_source.id,v_source.updated_at,'Autre organisation'),'Autre organisation refusée');
  perform pg_temp.ok(not exists(select 1 from public.invoices where corrects_invoice_id=v_source.id),'Avoir invisible à une autre organisation');
  perform pg_temp.login('technicien');
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_source.id,v_source.updated_at,'Sans permission'),'Technicien sans permission refusé');
  perform pg_temp.login('patron_a');
  insert into public.invoices (organization_id) values(v_org) returning * into v_source;
  perform pg_temp.refuses(format('select public.create_full_credit_note_draft(%L,%L,%L)',v_source.id,v_source.updated_at,'Source brouillon'),'Brouillon non émis refusé comme origine');
  perform pg_temp.complete_invoice(v_source.id);
  select * into v_source from public.invoices where id=v_source.id;
  select * into v_source from public.issue_invoice(v_source.id,v_source.updated_at);
  select * into v_draft from public.create_full_credit_note_draft(v_source.id,v_source.updated_at,'Brouillon supprimable');
  delete from public.invoices where id=v_draft.id;
  perform pg_temp.ok(not exists(select 1 from public.invoice_items where invoice_id=v_draft.id),'Supprimer le brouillon supprime ses lignes');
  select * into v_retry from public.create_full_credit_note_draft(v_source.id,v_source.updated_at,'Nouvelle préparation autorisée');
  perform pg_temp.ok(v_retry.id<>v_draft.id,'La suppression d''un brouillon permet une nouvelle préparation');
  reset role;
end $$;
